    { q: "Jika y = x + 1 dan y = x² - 1, apakah persamaan kuadratik yang terhasil?", qEn: "If y = x + 1 and y = x² - 1, what quadratic equation is formed?", options: ["x² - x - 2 = 0", "x² + x + 2 = 0", "x² - x = 0", "x² + 2 = 0"], correctIndex: 0, explanation: "x² - 1 = x + 1 -> x² - x - 2 = 0.", explanationEn: "x² - 1 = x + 1 simplifies to x² - x - 2 = 0." }
