  App.Data.t4.addmath.vektor = [
    { q: "Apakah magnitud bagi vektor v = 3i + 4j?", qEn: "Find the magnitude of vector v = 3i + 4j.", options: ["5", "7", "12", "25"], correctIndex: 0, explanation: "|v| = √(3² + 4²) = √(9 + 16) = √25 = 5.", explanationEn: "√(3² + 4²) = 5." },
    { q: "Apakah vektor unit dalam arah v = 3i + 4j?", qEn: "Find the unit vector in the direction of v = 3i + 4j.", options: ["(3i + 4j) / 5", "3i + 4j", "(3i + 4j) / 7", "(4i + 3j) / 5"], correctIndex: 0, explanation: "Vektor unit = v / |v| = (3i + 4j)/5.", explanationEn: "Unit vector = v / |v|." },
    { q: "Jika vektor a dan b adalah selari, maka...", qEn: "If vectors a and b are parallel, then...", options: ["a = kb bagi suatu pemalar bukan sifar k", "a · b = 1", "|a| = |b| sentiasa", "a + b = 0 sentiasa"], optionsEn: ["a = kb for some non-zero scalar k", "a · b = 1", "|a| = |b| always", "a + b = 0 always"], correctIndex: 0, explanation: "Vektor selari ialah gandaan skalar antara satu sama lain.", explanationEn: "Parallel vectors are scalar multiples of each other." },
    { q: "Mengikut Hukum Segi Tiga penambahan vektor, AB + BC = ...", qEn: "By the Triangle Law of vector addition, AB + BC = ...", options: ["AC", "CA", "BA", "0"], correctIndex: 0, explanation: "AB + BC = AC.", explanationEn: "AB + BC = AC." },
    { q: "Jika A(1, 2) dan B(5, 8), apakah vektor AB?", qEn: "If A(1, 2) and B(5, 8), find vector AB.", options: ["4i + 6j", "6i + 10j", "-4i - 6j", "5i + 8j"], correctIndex: 0, explanation: "AB = OB - OA = (5-1)i + (8-2)j = 4i + 6j.", explanationEn: "AB = (5-1)i + (8-2)j = 4i + 6j." }
  ];

